export function SearchResults({
  query = "{{query}}",
  count = {{count}},
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  const items = [
    { title: `Q3 ${query} overview`, meta: "Docs · updated 2 days ago" },
    { title: `${query} planning notes`, meta: "Wiki · updated 5 days ago" },
    { title: `Archive: ${query} v1`, meta: "Docs · updated 3 weeks ago" },
  ];
  return (
    <section style={{ display: "block", fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 380 }}>
      <p role="status" style={{ margin: "0 0 10px", fontSize: 12.5, color: "#24143090" }}>{count} results for "{query}"</p>
      {count > 0 ? (
        <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "grid", gap: 8 }}>
          {items.map((item) => (
            <li key={item.title} style={{ padding: "10px 12px", background: "#FAF7F2", border: "1px solid #24143018", borderLeft: `3px solid ${accent}`, borderRadius: radius }}>
              <p style={{ margin: "0 0 2px", fontWeight: 600 }}>{item.title}</p>
              <p style={{ margin: 0, fontSize: 12, color: "#24143080" }}>{item.meta}</p>
            </li>
          ))}
        </ul>
      ) : (
        <div style={{ padding: "20px 16px", textAlign: "center", background: "#24143008", border: "1px dashed #24143030", borderRadius: radius }}>
          <p style={{ margin: "0 0 4px", fontWeight: 600 }}>No results for "{query}"</p>
          <p style={{ margin: 0, fontSize: 12.5, color: "#24143080" }}>Try a different spelling or a broader term.</p>
        </div>
      )}
    </section>
  );
}
